fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    let mut seed: i32 = host::display::state_get(1);
    if seed == 0 { seed = 424242; }
    if down == 1 && prev == 0 {
        seed = seed * 1103515245 + 12345;
        host::display::state_set(1, seed);
    }
    host::display::state_set(0, down);
    host::display::clear(0x030308);
    let mut px: i32 = 0;
    let mut py: i32 = 0;
    let mut i: i32 = 0;
    while i < 12 {
        let mut hsh: i32 = seed + i * 2654435761;
        hsh = hsh * 1103515245 + 12345;
        let x: i32 = 40 + ((hsh >> 16) & 32767) % (w - 80);
        hsh = hsh * 1103515245 + 12345;
        let y: i32 = 40 + ((hsh >> 16) & 32767) % (h - 80);
        if i > 0 {
            host::display::draw_line(px, py, x, y, 0x2a3550);
        }
        px = x;
        py = y;
        i = i + 1;
    }
    let mut j: i32 = 0;
    while j < 12 {
        let mut hsh: i32 = seed + j * 2654435761;
        hsh = hsh * 1103515245 + 12345;
        let x: i32 = 40 + ((hsh >> 16) & 32767) % (w - 80);
        hsh = hsh * 1103515245 + 12345;
        let y: i32 = 40 + ((hsh >> 16) & 32767) % (h - 80);
        let mut tw: i32 = seed + j * 31 + t / 10;
        tw = tw * 1103515245 + 12345;
        let s: i32 = 2 + ((tw >> 16) & 3);
        host::display::fill_rect(x - s / 2, y - s / 2, s, s, 0xf0f6ff);
        j = j + 1;
    }
    host::display::present();
}
